<tr><td><strong>#<?php echo intval($delivery['order_id']); ?></strong><br><span style="font-size: 0.75rem; color: var(--text-muted);"><?php echo htmlspecialchars(date('M d, H:i', strtotime($delivery['created_at']))); ?></span></td><td><strong><?php echo htmlspecialchars($delivery['restaurant_name']); ?></strong><br><span style="font-size: 0.8rem; color: var(--text-muted);"><?php echo htmlspecialchars($delivery['restaurant_address']); ?></span></td><td><strong><?php echo htmlspecialchars($delivery['customer_name']); ?></strong><br><span style="font-size: 0.8rem; color: var(--text-muted);">📞 <?php echo htmlspecialchars($delivery['customer_phone'] ?? 'N/A'); ?></span></td><td><?php echo htmlspecialchars($delivery['delivery_address']); ?></td><td><span class="badge <?php echo $delivery['delivery_status'] === 'Pending Assignment' ? 'badge-pending' : 'badge-rider'; ?>"><?php echo htmlspecialchars($delivery['delivery_status']); ?></span></td><td><div class="inline-form" data-delivery="<?php echo intval($delivery['delivery_id']); ?>" style="flex-wrap: wrap; min-width: 190px;"><?php if ($delivery['delivery_status'] === 'Pending Assignment'): ?><button class="btn btn-primary btn-sm" data-action="accept">Accept</button><?php elseif ($delivery['delivery_status'] === 'Assigned'): ?><button class="btn btn-primary btn-sm" data-action="pickup">Confirm pickup</button><button class="btn btn-secondary btn-sm" data-action="update">Update</button><button class="btn btn-danger btn-sm" data-action="cancel">Cancel</button><?php elseif ($delivery['delivery_status'] === 'Picked Up'): ?><button class="btn btn-primary btn-sm" data-action="deliver">Mark delivered</button><button class="btn btn-secondary btn-sm" data-action="update">Update</button><button class="btn btn-danger btn-sm" data-action="cancel">Cancel</button><?php endif; ?><input class="form-control rider-note" maxlength="500" placeholder="Delivery information"></div></td></tr>
